package ArraysPractice;

public class Patterns16 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub

		for(int i =4;i>=1;i--)
		{
			for(int j=1;j<=i;j++)
			{
				System.out.print(j+" ");
			}
			System.out.println();
		}
	}

}
//output
/*
 1 2 3 4
 1 2 3
 1 2 
 1
4 4 4 4 
3 3 3 
2 2 
1 

*/
